public class InnerExpressGatewayServiceExpressGatewayContainerFactory(Action<Humidifier.ECS.ExpressGatewayServiceTypes.ExpressGatewayContainer> factoryAction = null) : SubResourceFactory<Humidifier.ECS.ExpressGatewayServiceTypes.ExpressGatewayContainer>
{

    internal InnerExpressGatewayServiceExpressGatewayRepositoryCredentialsFactory RepositoryCredentialsFactory { get; set; }

    internal InnerExpressGatewayServiceExpressGatewayServiceAwsLogsConfigurationFactory AwsLogsConfigurationFactory { get; set; }

    protected override Humidifier.ECS.ExpressGatewayServiceTypes.ExpressGatewayContainer Create()
    {
        var expressGatewayContainerResult = CreateExpressGatewayContainer();
        factoryAction?.Invoke(expressGatewayContainerResult);

        return expressGatewayContainerResult;
    }

    private Humidifier.ECS.ExpressGatewayServiceTypes.ExpressGatewayContainer CreateExpressGatewayContainer()
    {
        var expressGatewayContainerResult = new Humidifier.ECS.ExpressGatewayServiceTypes.ExpressGatewayContainer();

        return expressGatewayContainerResult;
    }
    public override void CreateChildren(Humidifier.ECS.ExpressGatewayServiceTypes.ExpressGatewayContainer result)
    {
        base.CreateChildren(result);

        result.RepositoryCredentials ??= RepositoryCredentialsFactory?.Build();
        result.AwsLogsConfiguration ??= AwsLogsConfigurationFactory?.Build();
    }

} // End Of Class

